import math

EPS = 1e-10

def require(cond, msg):
    if not cond:
        raise AssertionError(msg)

def clamp_int(v, lo, hi):
    if v < lo:
        return lo
    if v > hi:
        return hi
    return int(v)

def round_half_up(x):
    return int(math.floor(x + 0.5))

def round_even(x):
    return int(round(x))

def encode_int_zero(x, s, z, lo, hi):
    return clamp_int(round_half_up(x / s) + z, lo, hi)

def encode_real(x, s, b, lo, hi):
    return clamp_int(round_half_up((x - b) / s), lo, hi)

def decode_int(q, s, z):
    return s * (q - z)

def decode_real(q, s, b):
    return b + s * q

def transpose(A):
    return [[A[r][c] for r in range(len(A))] for c in range(len(A[0]))]

def mat_mul(A, B):
    return [[sum(A[i][k] * B[k][j] for k in range(len(B))) for j in range(len(B[0]))] for i in range(len(A))]

def mat_close(A, B, tol=1e-9):
    if len(A) != len(B) or len(A[0]) != len(B[0]):
        return False
    for i in range(len(A)):
        for j in range(len(A[0])):
            if abs(A[i][j] - B[i][j]) > tol:
                return False
    return True

def cholesky_lower(A):
    n = len(A)
    L = [[0.0] * n for _ in range(n)]
    for i in range(n):
        for j in range(i + 1):
            acc = A[i][j] - sum(L[i][k] * L[j][k] for k in range(j))
            if i == j:
                require(acc > 0.0, 'matrix is not positive definite')
                L[i][j] = math.sqrt(acc)
            else:
                L[i][j] = acc / L[j][j]
    return L

def chol_solve(L, b):
    n = len(L)
    y = [0.0] * n
    for i in range(n):
        acc = b[i] - sum(L[i][k] * y[k] for k in range(i))
        y[i] = acc / L[i][i]
    x = [0.0] * n
    for i in range(n - 1, -1, -1):
        acc = y[i] - sum(L[k][i] * x[k] for k in range(i + 1, n))
        x[i] = acc / L[i][i]
    return x

def inverse_spd(A):
    n = len(A)
    L = cholesky_lower(A)
    inv = [[0.0] * n for _ in range(n)]
    for c in range(n):
        e = [0.0] * n
        e[c] = 1.0
        col = chol_solve(L, e)
        for r in range(n):
            inv[r][c] = col[r]
    return inv

def upper_factor_of_inverse(H):
    Hinv = inverse_spd(H)
    C = cholesky_lower(Hinv)
    return transpose(C)

def upper_chol_of(H):
    return transpose(cholesky_lower(H))

def solve_dense(A, b):
    n = len(A)
    M = [list(A[i]) + [b[i]] for i in range(n)]
    for c in range(n):
        p = c
        for r in range(c + 1, n):
            if abs(M[r][c]) > abs(M[p][c]):
                p = r
        require(abs(M[p][c]) > 1e-14, 'singular reference system')
        if p != c:
            M[c], M[p] = M[p], M[c]
        piv = M[c][c]
        for k in range(c, n + 1):
            M[c][k] /= piv
        for r in range(n):
            if r == c:
                continue
            fac = M[r][c]
            if abs(fac) > 1e-18:
                for k in range(c, n + 1):
                    M[r][k] -= fac * M[c][k]
    return [M[i][n] for i in range(n)]

def quant_scalar(v):
    return clamp_int(round_half_up(v), -8, 8)

def gptq_block(W, H, R, B):
    d = len(H)
    rows = len(W)
    WW = [row[:] for row in W]
    Q = [[0] * d for _ in range(rows)]
    for i in range(0, d, B):
        end = min(i + B, d)
        width = end - i
        E = [[0.0] * width for _ in range(rows)]
        for j in range(i, end):
            for r in range(rows):
                q = quant_scalar(WW[r][j])
                Q[r][j] = q
                E[r][j - i] = (WW[r][j] - q) / R[j][j]
            for r in range(rows):
                for k in range(j, end):
                    WW[r][k] -= E[r][j - i] * R[j][k]
        if end < d:
            for r in range(rows):
                for k in range(end, d):
                    acc = 0.0
                    for t in range(width):
                        acc += E[r][t] * R[i + t][k]
                    WW[r][k] -= acc
    return Q

def gptq_reference(W, H):
    d = len(H)
    rows = len(W)
    WW = [row[:] for row in W]
    Q = [[0] * d for _ in range(rows)]
    for j in range(d):
        for r in range(rows):
            q = quant_scalar(WW[r][j])
            Q[r][j] = q
        if j + 1 < d:
            F = list(range(j + 1, d))
            A = [[H[a][b] for b in F] for a in F]
            rhs = [H[a][j] for a in F]
            sol = solve_dense(A, rhs)
            for r in range(rows):
                e = WW[r][j] - Q[r][j]
                for t, k in enumerate(F):
                    WW[r][k] += e * sol[t]
    return Q

def quad(e, H):
    total = 0.0
    for i in range(len(e)):
        for j in range(len(e)):
            total += e[i] * H[i][j] * e[j]
    return total

def objective(W, Q, H):
    total = 0.0
    for r in range(len(W)):
        e = [W[r][c] - Q[r][c] for c in range(len(H))]
        total += quad(e, H)
    return total

def test_rounding_contract():
    for x, want in ((0.5, 1), (-0.5, 0), (1.5, 2), (-1.5, -1), (2.5, 3)):
        require(round_half_up(x) == want, 'half-up tie rule mismatch')
    q_int = encode_int_zero(0.5, 1.0, 1, 0, 3)
    q_real = encode_real(0.5, 1.0, -1.0, 0, 3)
    require(q_int == 2 and q_real == 2, 'canonical paths should agree under half-up')
    require(abs(decode_int(q_int, 1.0, 1) - decode_real(q_real, 1.0, -1.0)) < EPS, 'decode mismatch')
    q_pre_even = clamp_int(round_even(0.5) + 1, 0, 3)
    q_post_even = clamp_int(round_even((0.5 - (-1.0)) / 1.0), 0, 3)
    require(q_pre_even == 1 and q_post_even == 2, 'tie-location negative control missing')
    for t in (0.5, -0.5, 1.5, -1.5, 2.25, -2.25):
        for dz in (-3, -1, 1, 4):
            require(round_half_up(t + dz) == round_half_up(t) + dz, 'half-up lost integer translation')
    require(round_even(0.5 + 1) != round_even(0.5) + 1, 'nearest-even should expose non-invariance')
    print('rounding: half-up int q=2 real q=2; nearest-even pre/post=1/2')

def test_decode_and_padding():
    s = 0.5
    z = 3
    require(abs(decode_int(z, s, z)) < EPS, 'integer zero code does not decode to zero')
    valid_codes = [1, 5]
    weights = [2, -3]
    base = sum(s * (valid_codes[i] - z) * weights[i] for i in range(2))
    with_pad = base + s * (z - z) * 7
    require(abs(with_pad - base) < EPS, 'integer-zero padding changed reduction')
    b_arb = -0.2
    s_arb = 0.5
    ratio = -b_arb / s_arb
    require(abs(ratio - round_half_up(ratio)) > 1e-9, 'arbitrary offset was incorrectly rewriteable')
    lo, hi, levels = -2.0, 6.0, 16
    step = (hi - lo) / (levels - 1)
    z_star = -lo / step
    require(abs(z_star - 3.75) < 1e-9, 'real grid zero position mismatch')
    q_near = round_half_up((0.0 - lo) / step)
    require(q_near == 4, 'nearest zero code mismatch')
    zero_error = abs(decode_real(q_near, step, lo))
    require(zero_error > 1e-3, 'real-offset grid wrongly treated as exact zero')
    pad_contribution = 15.0 * decode_real(q_near, step, lo)
    require(abs(pad_contribution - 2.0) < 1e-9, 'padding counterexample magnitude mismatch')
    valid_total = 31.0
    unmasked = valid_total + pad_contribution
    masked = valid_total
    require(abs(unmasked - valid_total) > 1.0 and abs(masked - valid_total) < EPS, 'mask did not remove invalid pad')
    print('padding: integer zero exact; real grid nearest error %.12f, pad*15 %.12f' % (zero_error, pad_contribution))

def test_gptq_factor():
    H = [[2.0, 0.4], [0.4, 1.0]]
    Hinv = inverse_spd(H)
    R = upper_factor_of_inverse(H)
    require(mat_close(mat_mul(transpose(R), R), Hinv), 'R is not an inverse-Hessian factor')
    ratio = R[0][1] / R[0][0]
    require(abs(ratio + 0.4) < 1e-9, 'correct inverse-factor row ratio mismatch')
    Rwrong = upper_chol_of(H)
    wrong_ratio = Rwrong[0][1] / Rwrong[0][0]
    require(abs(wrong_ratio - 0.2) < 1e-9, 'wrong-factor row ratio mismatch')
    obj0 = quad([-0.3, 0.0], H)
    objc = quad([-0.3, 0.12], H)
    objw = quad([-0.3, -0.06], H)
    require(abs(obj0 - 0.18) < 1e-9, 'base objective mismatch')
    require(abs(objc - 0.1656) < 1e-9, 'correct objective mismatch')
    require(abs(objw - 0.198) < 1e-9, 'wrong objective mismatch')
    require(objc < obj0 < objw, 'factor negative control not separated')
    print('gptq-factor: rows %.3f vs %.3f, objectives %.4f/%.4f/%.4f' % (ratio, wrong_ratio, obj0, objc, objw))

def test_gptq_short_block_and_negative():
    H3 = [[2.0, 0.4, 0.05], [0.4, 1.0, -0.1], [0.05, -0.1, 0.8]]
    R3 = upper_factor_of_inverse(H3)
    W3 = [[-0.3, 0.55, 0.2], [1.35, -0.7, 0.31]]
    q_block = gptq_block(W3, H3, R3, 2)
    q_ref = gptq_reference(W3, H3)
    require(q_block == q_ref, 'blocked GPTQ differs from constrained quadratic reference')
    Wneg = [[-0.3, 0.55, 0.2]]
    qc = gptq_block(Wneg, H3, R3, 2)
    qr = gptq_reference(Wneg, H3)
    require(qc == qr, 'controlled blocked GPTQ differs from reference')
    Rwrong3 = upper_chol_of(H3)
    qw = gptq_block(Wneg, H3, Rwrong3, 2)
    require(qw != qc, 'wrong factor was not detected by code mismatch')
    oc = objective(Wneg, qc, H3)
    ow = objective(Wneg, qw, H3)
    require(ow > oc + 1e-9, 'wrong factor did not worsen controlled objective')
    print('gptq-block: d=3 B=2 short tail; codes %s vs %s, obj %.6f/%.6f' % (qc, qw, oc, ow))

def test_group_scale_inside_reduction():
    c1, c2 = [1, 2], [3, 4]
    s1, s2 = 0.5, 2.0
    true_value = s1 * sum(c1) + s2 * sum(c2)
    wrong_value = s1 * sum(c1 + c2)
    require(abs(true_value - wrong_value) > 1e-9, 'group-scale negative control was not detected')
    print('group-scale: true %.6f wrong-global %.6f' % (true_value, wrong_value))

def main():
    test_rounding_contract()
    test_decode_and_padding()
    test_gptq_factor()
    test_gptq_short_block_and_negative()
    test_group_scale_inside_reduction()
    print('scope: arithmetic, rounding placement, padding, Cholesky-GPTQ; no runtime or GPU measurement')
    print('PASS: K-ALG-005 scoped contract and negative-control checks')

if __name__ == '__main__':
    main()
